/* ============================================================
   logo-data.js -- brasao da empresa (enops engenharia) embutido em
   Base64, para uso no cabecalho dos PDFs gerados pelo jsPDF sem
   depender de fetch/CORS ao abrir o app via file:// local.

   Gerado a partir de app/assets/brasao.png (400x400px, fundo branco).
   Se este arquivo nao existir/nao carregar, window.LOGO_BASE64 fica
   undefined e o cabecalho do PDF simplesmente nao desenha o brasao
   (bloco opcional, nao quebra nada).
   ============================================================ */
window.LOGO_BASE64 = "data:image/png;base64,";
